theorem lg_target {α : Type*} (A B C : Set α) (h₁ : A ⊆ B) (h₂ : B ⊆ C) : A \ C = ∅ := by
  apply Eq.trans;
  exact Set.subset.antisymm (Set.Subset.trans h₁ h₂) (Set.Subset.trans (Set.Subset.refl A) (Set.Subset.refl C));
  exact Set.Subset.trans (Set.Subset.refl A) (Set.Subset.refl C)
```
